def parse_roman(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    subtractive = {
        'IV': 4, 'IX': 9,
        'XL': 40, 'XC': 90,
        'CD': 400, 'CM': 900
    }
    i = 0
    total = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in subtractive:
            total += subtractive[s[i:i+2]]
            i += 2
        else:
            if s[i] not in values:
                raise ValueError('invalid symbol')
            total += values[s[i]]
            i += 1
    return total
```

